import { Link } from 'react-router-dom';
import RolesList from '../components/rolesList/RolesList';
import { useHasPermission } from '../hooks/usePermission';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import { Plus } from 'lucide-react';

const RolesListPage = () => {
    const can = useHasPermission('list_role');
    const canCreate = useHasPermission('create_role');

    if (!can) {
        return <p className="mt-8 px-4 text-sm text-white-blue-700">ليس لديك صلاحية عرض الأدوار.</p>;
    }

    return (
        <div className="mx-auto mt-6 w-full max-w-6xl px-4 pb-14">
            <div className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between">
                <div>
                    <h1 className="text-2xl font-bold tracking-tight text-primery-blue-600">الأدوار</h1>
                    <p className="mt-2 max-w-xl text-sm leading-relaxed text-white-blue-700">
                        الأدوار تحدد مجموعة الصلاحيات لكل مستخدم إداري. يمكنك تعديل صلاحيات الدور من شاشة التعديل.
                    </p>
                </div>
                {canCreate && (
                    <PrimaryButton asChild className="inline-flex shrink-0 items-center gap-2 !py-2.5">
                        <Link to="/access-control/roles/add">
                            <Plus className="h-4 w-4" />
                            إضافة دور
                        </Link>
                    </PrimaryButton>
                )}
            </div>
            <div className="mt-8">
                <RolesList />
            </div>
        </div>
    );
};

export default RolesListPage;
