import { useCallback, useState } from 'react';
import { endpoints } from '@/lib/axios/axios-global';
import { apiGet } from '@/lib/axios/axios-utils';
import { DataTableToolbar } from './data-table-toolbar';
import { columns } from './columns';
import { DataTable } from '@/components/tables/customTable/data-table';
import { FetchDataOptions } from '@/types/table.types';
import { RoleRow } from '../../types/roles.types';

type RoleListPayload = {
    data: RoleRow[];
    pagination: {
        current_page: number;
        last_page: number;
        per_page: number;
        total: number;
    };
};

const RolesList = () => {
    const [data, setData] = useState<RoleRow[]>([]);
    const [pageCount, setPageCount] = useState(0);
    const [totalCount, setTotalCount] = useState(0);
    const [isLoading, setIsLoading] = useState(false);
    const fetchData = useCallback(async (options: FetchDataOptions) => {
        setIsLoading(true);
        try {
            const response = await apiGet<{ data: RoleListPayload }>({
                endpoint: endpoints.accessControl.roleList,
                queryParams: {
                    page: options.pageIndex + 1,
                    pageSize: 10,
                    ...options.filters,
                    search: options.globalFilter,
                },
            });
            const payload = response.data?.data as RoleListPayload | undefined;
            const rows = payload?.data ?? [];
            const pagination = payload?.pagination;
            const perPage = pagination?.per_page ?? 10;
            const total = pagination?.total ?? rows.length;
            setData(rows);
            setPageCount(Math.max(1, Math.ceil(total / perPage)));
            setTotalCount(total);
        } catch (error) {
            console.error('Error fetching roles:', error);
            setData([]);
            setPageCount(0);
            setTotalCount(0);
        } finally {
            setIsLoading(false);
        }
    }, []);

    return (
        <div className="mb-6 overflow-hidden rounded-2xl border border-[#E4E2EC] bg-white shadow-[0_12px_40px_-16px_rgba(12,12,13,0.12)]">
            <DataTable
                columns={columns}
                data={data}
                pageCount={pageCount}
                totalCount={totalCount}
                onFetchData={fetchData}
                DataTableToolbar={DataTableToolbar}
                isLoading={isLoading}
            />
        </div>
    );
};

export default RolesList;
