import type { Table } from '@tanstack/react-table';
import { Input } from '@/components/ui/input';
import SearchIcon from '@/components/icons/Search';
import { PrimaryButton } from '@/components/buttons/PrimaryButton';
import AddIcon from '@/components/icons/AddIcon';
import { Link } from 'react-router-dom';
import { RoleRow } from '../../types/roles.types';
import { Filters } from '@/types/table.types';
import { useHasPermission } from '../../hooks/usePermission';

interface DataTableToolbarProps {
    table?: Table<RoleRow>;
    globalFilter: string;
    setGlobalFilter: (value: string) => void;
    filters?: Filters;
    setFilters?: (value: Filters) => void;
    data?: RoleRow[];
    handleRefreshTable?: () => void;
}

export function DataTableToolbar({ globalFilter, setGlobalFilter }: DataTableToolbarProps) {
    const canCreate = useHasPermission('create_role');
    return (
        <div className="flex flex-col gap-4 border-b border-[#EEF0F4] bg-[#FAFAFC] p-4 sm:flex-row sm:items-center sm:justify-between">
            <div className="flex max-w-md flex-1 flex-row items-center rounded-lg border border-[#E4E2EC] bg-white p-2 shadow-sm">
                <Input
                    placeholder="ابحث باسم الدور"
                    value={globalFilter}
                    onChange={(event) => setGlobalFilter(event.target.value)}
                    className="border-none p-0 text-sm text-white-blue-900 outline-none focus-visible:ring-0 placeholder:text-white-blue-500"
                />
                <span className="shrink-0 ps-2">
                    <SearchIcon className="text-white-blue-600" />
                </span>
            </div>
            {canCreate && (
                <PrimaryButton asChild className="flex w-full shrink-0 items-center justify-center gap-2 !py-2 sm:hidden">
                    <Link to="/access-control/roles/add">
                        <AddIcon />
                        إضافة دور
                    </Link>
                </PrimaryButton>
            )}
        </div>
    );
}
